	@ParameterizedTest
	@CsvSource({ "o,false", "source,false", "o,true", "source,true" })
	void tripleRefJoinGroupRestoresPreparedBinding(String column, boolean mixedSources) {
		IRI sourcePredicate = Values.iri("urn:source");
		var members = mixedSources ? List.of(left, right, local) : List.of(left, right);
		for (var member : members) {
			try (var connection = member.getConnection()) {
				var factory = connection.getValueFactory();
				var reifier = factory.createBNode();
				connection.add(reifier, RDF.REIFIES, factory.createTripleTerm(A, PREDICATE, FIRST));
				connection.add(reifier, sourcePredicate, SECOND);
				var otherReifier = factory.createBNode();
				connection.add(otherReifier, RDF.REIFIES, factory.createTripleTerm(B, PREDICATE, SECOND));
				connection.add(otherReifier, sourcePredicate, FIRST);
			}
		}

		try (var connection = federation.getConnection()) {
			var query = connection.prepareTupleQuery("""
					PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
					SELECT ?s ?o ?source WHERE {
					  ?reifier rdf:reifies <<( ?s <urn:p> ?o )>> ;
					           <urn:source> ?source .
					}
					""");
			query.setBinding(column, column.equals("o") ? FIRST : SECOND);
			assertThat(QueryResults.asList(query.evaluate()))
					.extracting(row -> tuple(row.getValue("s"), row.getValue("o"), row.getValue("source")))
					.containsExactlyElementsOf(Collections.nCopies(members.size(), tuple(A, FIRST, SECOND)));
		}
	}

	@ParameterizedTest
	@CsvSource({ "CAPTURED,false", "CAPTURED,true", "CONSTANT,false", "CONSTANT,true", "INPUT,false", "INPUT,true" })
	void mixedBlockRetainsExistenceAndMatchMultiplicities(PredicateBinding predicateBinding, boolean optional) {
		try (var first = left.getConnection(); var second = right.getConnection()) {
			first.add(A, PREDICATE, FIRST);
			second.add(A, PREDICATE, FIRST);
			first.add(B, PREDICATE, FIRST);
			first.add(B, PREDICATE, SECOND);
			second.add(B, PREDICATE, FIRST);
		}

		Var predicate = switch (predicateBinding) {
		case CAPTURED -> capturedPredicate();
		case CONSTANT -> Var.of("constant", PREDICATE, true, true);
		case INPUT -> Var.of("p");
		};
		var statement = new StatementSourcePattern(new StatementPattern(Var.of("s"), predicate, Var.of("o")),
				queryInfo);
		statement.addStatementSource(LEFT);
		statement.addStatementSource(RIGHT);
		var fullyBound = input(A);
		fullyBound.addBinding("o", FIRST);
		var free = input(B);
		var unmatched = input(MISSING);
		if (predicateBinding == PredicateBinding.INPUT) {
			fullyBound.addBinding("p", PREDICATE);
			free.addBinding("p", PREDICATE);
			unmatched.addBinding("p", PREDICATE);
		}

		List<BindingSet> input = List.of(fullyBound, free, unmatched, fullyBound);
		var expected = new ArrayList<BindingSet>();
		for (BindingSet row : input) {
			var scalar = evaluate(statement, List.of(row), false);
			expected.addAll(optional && scalar.isEmpty() ? List.of(row) : scalar);
		}
		assertThat(expected).hasSize(optional ? 6 : 5);
		assertThat(evaluate(statement, input, optional)).containsExactlyInAnyOrderElementsOf(expected);
	}

