	@ParameterizedTest
	@CsvSource({ "false,false", "false,true", "true,false", "true,true" })
	void rowOrdinalNeverUsesPublicVariableName(boolean nativeGraph, boolean optional) {
		var graph = Values.bnode("named");
		try (var connection = local.getConnection()) {
			if (nativeGraph) {
				connection.add(A, PREDICATE, FIRST, graph);
				connection.add(B, PREDICATE, SECOND, graph);
			} else {
				connection.add(A, PREDICATE, FIRST);
				connection.add(B, PREDICATE, SECOND);
			}
		}
		var pattern = nativeGraph
				? new StatementPattern(Scope.NAMED_CONTEXTS, Var.of("s"), capturedPredicate(), Var.of("__index"),
						Var.of("g"))
				: new StatementPattern(Var.of("s"), capturedPredicate(), Var.of("__index"));
		var statement = new ExclusiveStatement(pattern, LOCAL, queryInfo);
		if (nativeGraph) {
			statement.setResolvedGraphSelection(new ResolvedGraphSelection(graph, graph, false));
		}
		var first = input(A);
		first.addBinding("__index_0", SECOND);
		var second = input(B);
		var unmatched = input(MISSING);
		var expected = new ArrayList<BindingSet>(List.of(
				matched(first, "__index", FIRST), matched(second, "__index", SECOND),
				matched(first, "__index", FIRST)));
		if (optional) {
			expected.add(unmatched);
		}

		assertThat(evaluate(statement, List.of(first, second, first, unmatched), optional))
				.containsExactlyInAnyOrderElementsOf(expected);
	}

	@ParameterizedTest
	@CsvSource({
			"false,false,false", "false,false,true", "false,true,false", "false,true,true",
			"true,false,false", "true,false,true", "true,true,false", "true,true,true"
	})
	void explicitNullInOrdinaryColumnRetainsScalarLocalDomain(boolean preparedSource, boolean optional,
			boolean singleton) {
		try (var connection = (preparedSource ? left : local).getConnection()) {
			connection.add(A, PREDICATE, FIRST);
			connection.add(A, PREDICATE, SECOND);
			connection.add(B, PREDICATE, SECOND);
		}

		var statement = new ExclusiveStatement(new StatementPattern(Var.of("s"), capturedPredicate(), Var.of("o")),
				preparedSource ? LEFT : LOCAL, queryInfo);
		var explicitNull = input(A);
		explicitNull.setBinding("o", null);
		explicitNull.setBinding("outside", null);
		explicitNull.addBinding("passthrough", FIRST);
		var missingNull = input(MISSING);
		missingNull.setBinding("o", null);
		var free = input(B);
		var expected = new ArrayList<BindingSet>(List.of(matched(explicitNull, "o", null),
				matched(explicitNull, "o", null)));
		if (singleton) {
			assertThat(evaluate(statement, List.of(explicitNull), optional)).containsExactlyElementsOf(expected);
			return;
		}
		expected.addAll(List.of(matched(free, "o", SECOND), matched(explicitNull, "o", null),
				matched(explicitNull, "o", null)));
		if (optional) {
			expected.add(missingNull);
		}

		assertThat(evaluate(statement, List.of(explicitNull, free, missingNull, delegated(explicitNull)), optional))
				.containsExactlyInAnyOrderElementsOf(expected);
	}

