	@ParameterizedTest
	@CsvSource({ "false,false", "false,true", "true,false", "true,true" })
	void varyingGraphSelectorsIncludeTheDefaultGraphAlias(boolean legacyAlias, boolean optional) {
		var alias = legacyAlias ? SESAME.NIL : RDF4J.NIL;
		var namedGraph = Values.iri("urn:named");
		try (var connection = left.getConnection()) {
			connection.add(A, PREDICATE, FIRST);
			connection.add(B, PREDICATE, SECOND, namedGraph);
		}

		var statement = new ExclusiveStatement(
				new StatementPattern(Scope.NAMED_CONTEXTS, Var.of("s"), capturedPredicate(), Var.of("o"), Var.of("g")),
				LEFT, queryInfo);
		var defaultInput = input(A);
		defaultInput.addBinding("g", alias);
		var namedInput = input(B);
		namedInput.addBinding("g", namedGraph);
		var absent = input(MISSING);
		absent.addBinding("g", alias);
		var expected = new ArrayList<BindingSet>(List.of(matched(defaultInput, "o", FIRST),
				matched(namedInput, "o", SECOND), matched(defaultInput, "o", FIRST)));
		if (optional) {
			expected.add(absent);
		}
		assertThat(evaluate(statement, List.of(defaultInput, absent, namedInput, defaultInput), optional))
				.containsExactlyInAnyOrderElementsOf(expected);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void capturedLiteralPreservesBackslashInBatchedQuery(boolean optional) {
		var literal = Values.literal("literal\\n");
		try (var connection = local.getConnection()) {
			connection.add(A, PREDICATE, literal);
			connection.add(B, PREDICATE, Values.literal("literal\n"));
		}

		var statement = new ExclusiveStatement(
				new StatementPattern(Var.of("s"), capturedPredicate(), Var.of("o", literal, false, false)),
				LOCAL, queryInfo);
		var matching = input(A);
		var unmatched = input(B);
		var expected = new ArrayList<BindingSet>(List.of(matched(matching, "o", literal)));
		if (optional) {
			expected.add(unmatched);
		}

		assertThat(evaluate(statement, List.of(matching, unmatched), optional))
				.containsExactlyInAnyOrderElementsOf(expected);
	}

	private List<BindingSet> evaluate(StatementTupleExpr statement, List<BindingSet> input, boolean optional) {
		try (var rows = optional ? strategy.evaluateLeftBoundJoinStatementPattern(statement, input)
				: strategy.evaluateBoundJoinStatementPattern(statement, input)) {
			return QueryResults.asList(rows);
		}
	}

	private static Var capturedPredicate() {
		return Var.of("p", PREDICATE, false, false);
	}

	private static QueryBindingSet input(IRI subject) {
		var row = new QueryBindingSet();
		row.addBinding("s", subject);
		return row;
	}

	private static BindingSet matched(BindingSet input, String name, Value value) {
		var row = new QueryBindingSet(input);
		row.setBinding("p", PREDICATE);
		row.setBinding(name, value);
		return row;
	}

	private static BindingSet delegated(BindingSet row) {
		BindingSet delegate = mock(BindingSet.class);
		when(delegate.getBindingNames()).thenReturn(row.getBindingNames());
		when(delegate.size()).thenReturn(row.size());
		when(delegate.iterator()).thenAnswer(invocation -> row.iterator());
		when(delegate.hasBinding(anyString())).thenAnswer(invocation -> row.hasBinding(invocation.getArgument(0)));
		when(delegate.getValue(anyString())).thenAnswer(invocation -> row.getValue(invocation.getArgument(0)));
		return delegate;
	}

	private static ManagedRepositoryEndpoint endpoint(StatementSource source, SailRepository repository,
			EndpointType type, EndpointClassification classification) {
		String id = source.getEndpointID();
		String location = "http://" + id;
		return new ManagedRepositoryEndpoint(new RepositoryInformation(id, location, location, type), location,
				classification, repository);
	}
